    async function startLogin(provider) {
      clearLoginTimer();
      setMessage('\u6B63\u5728\u751F\u6210\u4E8C\u7EF4\u7801...');
      const result = await api('/website/api/login/start',{method:'POST',body:JSON.stringify({provider})});
      loginTask = { provider, taskId: result.taskId };
      showQr(result.qrImage, result.msg || '\u8BF7\u626B\u7801\u786E\u8BA4');
      if (isManualLoginProvider(provider)) {
        setMessage(manualLoginMessage(provider));
        return;
      }
      loginTimer = setInterval(() => pollLogin().catch(handleError), 1500);
      await pollLogin();
    }

    async function startBiliLogin() {
      clearLoginTimer();
      setMessage('\u6B63\u5728\u751F\u6210 Bili \u4E8C\u7EF4\u7801...');
      const result = await api('/website/api/bili/login/start',{method:'POST',body:'{}'});
      loginTask = { provider: 'bili', taskId: result.taskId };
      showQr(result.qrImage, result.msg || '\u8BF7\u4F7F\u7528\u54D4\u54E9\u54D4\u54E9 App \u626B\u7801\u786E\u8BA4');
      if (isManualLoginProvider('bili')) {
        setMessage(manualLoginMessage('bili'));
        return;
      }
      loginTimer = setInterval(() => pollLogin().catch(handleError), 1500);
      await pollLogin();
    }

    async function pollLogin() {
      if (!loginTask || loginPolling) return;
      loginPolling = true;
      try {
        const path = loginTask.provider === 'bili' ? '/website/api/bili/login/poll' : '/website/api/login/poll';
        const result = await api(path,{method:'POST',body:JSON.stringify(loginTask)});
        setMessage(result.msg || '\u7B49\u5F85\u626B\u7801\u786E\u8BA4');
        if (result.status === 'success') {
          clearLoginTimer();
          toast(result.msg || '\u767B\u5F55\u6210\u529F');
          await refresh();
        } else if (result.terminal || result.status === 'expired' || result.status === 'error') {
          clearLoginTimer();
          setMessage(result.msg || '\u767B\u5F55\u5931\u8D25', true);
        }
      } finally {
        loginPolling = false;
      }
    }

    async function cancelLogin() {
      if (loginTask) {
        const path = loginTask.provider === 'bili' ? '/website/api/bili/login/cancel' : '/website/api/login/cancel';
        await api(path,{method:'POST',body:JSON.stringify(loginTask)});
      }
      clearLoginTimer();
      setMessage('\u5DF2\u53D6\u6D88\u767B\u5F55');
    }

    function clearLoginTimer() {
      if (loginTimer) clearInterval(loginTimer);
      loginTimer = null;
      loginTask = null;
      loginPolling = false;
    }

    function showQr(src, text) {
      const box = $('qrBox');
      const img = $('qrImage');
      if (!box || !img) return;
      img.src = src || '';
      box.style.display = 'block';
      const cancel = $('cancelLoginBtn');
      if (cancel) cancel.onclick = () => cancelLogin().catch(handleError);
      const confirm = $('confirmLoginBtn');
      if (confirm) {
        confirm.style.display = isManualLoginProvider(loginTask?.provider) ? 'inline-flex' : 'none';
        confirm.onclick = () => pollLogin().catch(handleError);
      }
      setMessage(text || '\u8BF7\u626B\u7801\u786E\u8BA4');
    }

    function updateOrderSelect(selected) {
      const select = $('panOrderSelect');
      select.innerHTML = editingOrder.map((id,i) => '<option value="' + i + '">' + (i + 1) + '. ' + escapeHtml(nameOf(id)) + '</option>').join('');
      select.selectedIndex = Math.max(0, Math.min(selected || 0, editingOrder.length - 1));
      setMessage('\u9884\u89C8\u987A\u5E8F\uFF1A' + editingOrder.map(nameOf).join(' > '));
    }
    function moveOrder(step) {
      const select = $('panOrderSelect');
      const i = select.selectedIndex < 0 ? 0 : select.selectedIndex;
      const j = i + step;
      if (j < 0 || j >= editingOrder.length) return;
      const tmp = editingOrder[i];
      editingOrder[i] = editingOrder[j];
      editingOrder[j] = tmp;
      updateOrderSelect(j);
    }
    function textarea(id,label,value){return '<div><label for="' + id + '">' + label + '</label><textarea id="' + id + '">' + escapeHtml(value || '') + '</textarea></div>'}
    function input(id,label,value){return '<div><label for="' + id + '">' + label + '</label><input id="' + id + '" value="' + escapeHtml(value || '') + '"></div>'}
    function actions(items){return '<div class="actions">' + items.map(i => '<button id="' + i[0] + '" class="' + (i[2] || '') + '">' + i[1] + '</button>').join('') + '</div>'}
    function qrBoxHtml(){return '<div id="qrBox" style="display:none;margin-top:14px"><img id="qrImage" style="width:230px;max-width:100%;display:block;background:#fff;padding:10px;border-radius:8px"><div class="qr-actions"><button class="confirm-login" id="confirmLoginBtn" style="display:none">\u626B\u7801\u540E\u70B9\u6211</button><button class="danger" id="cancelLoginBtn">\u53D6\u6D88\u767B\u5F55</button></div></div>'}
    function isManualLoginProvider(provider){return ['pan115','quark','ucCookie','ucToken','baidu','pan189','pan139','bili','guangya'].includes(provider)}
    function manualLoginMessage(provider){
      if (provider === 'quark') return '\u8BF7\u4F7F\u7528\u5938\u514B App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'ucCookie') return '\u8BF7\u4F7F\u7528 UC \u6D4F\u89C8\u5668\u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'ucToken') return '\u8BF7\u4F7F\u7528 UC \u6D4F\u89C8\u5668\u626B\u7801\u786E\u8BA4 TV Token\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'baidu') return '\u8BF7\u4F7F\u7528\u767E\u5EA6\u7F51\u76D8 App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'pan189') return '\u8BF7\u4F7F\u7528\u5929\u7FFC\u4E91\u76D8 App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'pan139') return '\u8BF7\u4F7F\u7528\u79FB\u52A8\u4E91\u76D8 App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'bili') return '\u8BF7\u4F7F\u7528\u54D4\u54E9\u54D4\u54E9 App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      if (provider === 'guangya') return '\u8BF7\u4F7F\u7528\u5149\u9E2D App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
      return '\u8BF7\u4F7F\u7528 115 App \u626B\u7801\u786E\u8BA4\uFF0C\u626B\u5B8C\u540E\u70B9\u51FB\u201C\u626B\u7801\u540E\u70B9\u6211\u201D';
    }
    function setMessage(text,bad){$('message').className = 'status ' + (bad ? 'bad' : ''); $('message').textContent = text || ''}
    function toast(text){const node=$('toast');node.textContent=text;node.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>node.classList.remove('show'),1900)}
    function statusClass(p){return p?.login ? 'ok' : p?.configured ? 'bad' : 'warn'}
    function guangYaSavedPhone(){try{return JSON.parse(secrets.guangya.token || '{}').phone || ''}catch{return ''}}
    function nameOf(id){return state.providerNames[id] || id}
    function labelOrder(value){return String(value || '').split(',').filter(Boolean).map(nameOf).join(' > ')}
    function formatBytes(size){const units=['B','KB','MB'];let value=Number(size||0),i=0;while(value>=1024&&i<units.length-1){value/=1024;i++}return (i?value.toFixed(1):String(value)) + units[i]}
    function escapeHtml(value){return String(value || '').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
    function handleError(error){const text=error?.message || String(error || '\u64CD\u4F5C\u5931\u8D25');setMessage(text,true);toast(text)}
    $('reloadBtn').onclick = () => refresh().catch(handleError);
    $('drawerClose').onclick = closeDrawer;
